#!/usr/bin/env bash
# Things a hosting business specifically needs day to day.

hx_mc_startscript() {
  hr; echo -e "  ${C_PURPLE}${C_BOLD}Minecraft start-script generator${C_RESET} (Aikar flags)"; hr
  local RAM; RAM=$(ask "RAM to allocate, in MB" "4096")
  local JAR; JAR=$(ask "Server jar filename" "server.jar")
  local OUT; OUT=$(ask "Write script to" "./start.sh")
  cat > "$OUT" <<EOF
#!/usr/bin/env bash
# Generated by The Axion Installer — Aikar's flags, tuned for ${RAM}MB.
java -Xms${RAM}M -Xmx${RAM}M \\
  -XX:+UseG1GC -XX:+ParallelRefProcEnabled -XX:MaxGCPauseMillis=200 \\
  -XX:+UnlockExperimentalVMOptions -XX:+DisableExplicitGC -XX:+AlwaysPreTouch \\
  -XX:G1NewSizePercent=30 -XX:G1MaxNewSizePercent=40 -XX:G1HeapRegionSize=8M \\
  -XX:G1ReservePercent=20 -XX:G1HeapWastePercent=5 -XX:G1MixedGCCountTarget=4 \\
  -XX:InitiatingHeapOccupancyPercent=15 -XX:G1MixedGCLiveThresholdPercent=90 \\
  -XX:G1RSetUpdatingPauseTimePercent=5 -XX:SurvivorRatio=32 -XX:+PerfDisableSharedMem \\
  -XX:MaxTenuringThreshold=1 -Dusing.aikars.flags=https://mcflags.emc.gs \\
  -Daikars.new.flags=true \\
  -jar ${JAR} nogui
EOF
  chmod +x "$OUT"
  hr; ok "Wrote ${OUT} — drop it next to ${JAR} and run it instead of 'java -jar'."
  press_enter
}

hx_panel_db_backup() {
  need_root; hr; echo -e "  ${C_PURPLE}${C_BOLD}Pterodactyl DB backup${C_RESET} (separate from generic folder backups)"; hr
  local PANEL; PANEL=$(ask "Panel install path" "/var/www/pterodactyl")
  [ -f "$PANEL/.env" ] || die "No panel .env found at $PANEL."
  local DB_NAME DB_USER DB_PASS
  DB_NAME=$(grep -oP '(?<=^DB_DATABASE=).*' "$PANEL/.env")
  DB_USER=$(grep -oP '(?<=^DB_USERNAME=).*' "$PANEL/.env")
  DB_PASS=$(grep -oP '(?<=^DB_PASSWORD=).*' "$PANEL/.env")
  local DEST; DEST=$(ask "Backup folder" "/backups/pterodactyl-db")
  local KEEP; KEEP=$(ask "Days to keep" "14")
  local SCHED; SCHED=$(ask "Cron schedule" "0 4 * * *")
  mkdir -p "$DEST"
  cat > /usr/local/bin/axion-panel-db-backup.sh <<EOF
#!/usr/bin/env bash
STAMP=\$(date +%Y%m%d-%H%M%S)
MYSQL_PWD='${DB_PASS}' mysqldump -u '${DB_USER}' '${DB_NAME}' | gzip > "${DEST}/panel-db-\${STAMP}.sql.gz"
find "${DEST}" -name 'panel-db-*.sql.gz' -mtime +${KEEP} -delete
EOF
  chmod +x /usr/local/bin/axion-panel-db-backup.sh
  ( crontab -l 2>/dev/null | grep -v 'axion-panel-db-backup.sh' ; echo "${SCHED} /usr/local/bin/axion-panel-db-backup.sh >> /var/log/axion-panel-db-backup.log 2>&1" ) | crontab -
  spin "Taking a backup right now to confirm it works" bash /usr/local/bin/axion-panel-db-backup.sh
  hr; ok "Panel DB '${DB_NAME}' backs up to ${DEST} on schedule '${SCHED}', keeping ${KEEP} days."
  press_enter
}

hx_wildcard_ssl() {
  need_root; hr; echo -e "  ${C_PURPLE}${C_BOLD}Wildcard SSL${C_RESET} (Cloudflare DNS challenge)"; hr
  echo -e "  ${C_GREY}For *.yourdomain.com — covers every node/VPS subdomain with one cert.${C_RESET}"
  spin "Installing certbot + Cloudflare DNS plugin" apt-get install -y certbot python3-certbot-dns-cloudflare
  local DOMAIN TOKEN
  DOMAIN=$(ask "Root domain (e.g. example.com)"); [ -z "$DOMAIN" ] && { warn "Cancelled."; press_enter; return; }
  TOKEN=$(ask_secret "Cloudflare API token (Zone:DNS:Edit permission)")
  mkdir -p /etc/letsencrypt
  printf 'dns_cloudflare_api_token = %s\n' "$TOKEN" > /etc/letsencrypt/cloudflare.ini
  chmod 600 /etc/letsencrypt/cloudflare.ini
  spin "Requesting wildcard cert for *.${DOMAIN}" certbot certonly \
    --dns-cloudflare --dns-cloudflare-credentials /etc/letsencrypt/cloudflare.ini \
    -d "*.${DOMAIN}" -d "${DOMAIN}" --non-interactive --agree-tos -m "$(ask "Email" "")"
  hr; ok "Cert: /etc/letsencrypt/live/${DOMAIN}/ — point your webserver(s) at fullchain.pem + privkey.pem. Auto-renews via certbot's own timer."
  press_enter
}

hx_discord_status() {
  need_root; hr; echo -e "  ${C_PURPLE}${C_BOLD}Discord status pings${C_RESET}"; hr
  local WEBHOOK; WEBHOOK=$(ask "Discord webhook URL")
  [ -z "$WEBHOOK" ] && { warn "Cancelled."; press_enter; return; }
  local LABEL; LABEL=$(ask "Label for this server (shown in the message)" "$(hostname)")
  cat > /usr/local/bin/axion-discord-ping.sh <<EOF
#!/usr/bin/env bash
MSG="\$1"
curl -s -H "Content-Type: application/json" -d "{\"content\": \"**${LABEL}**: \${MSG}\"}" "${WEBHOOK}" >/dev/null
EOF
  chmod +x /usr/local/bin/axion-discord-ping.sh
  # boot notification
  cat > /etc/systemd/system/axion-boot-notify.service <<'EOF'
[Unit]
Description=Notify Discord on boot
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/axion-discord-ping.sh "🟢 Server just booted up."

[Install]
WantedBy=multi-user.target
EOF
  spin "Enabling boot notification" bash -c "systemctl daemon-reload && systemctl enable axion-boot-notify"
  if confirm "Also send a daily health check-in (uptime/load/disk)?"; then
    cat > /usr/local/bin/axion-discord-health.sh <<'EOF'
#!/usr/bin/env bash
MSG="Daily check-in — up $(uptime -p), load $(cut -d' ' -f1-3 /proc/loadavg), disk $(df -h / | awk 'NR==2{print $5}') used"
/usr/local/bin/axion-discord-ping.sh "$MSG"
EOF
    chmod +x /usr/local/bin/axion-discord-health.sh
    ( crontab -l 2>/dev/null | grep -v 'axion-discord-health.sh' ; echo "0 9 * * * /usr/local/bin/axion-discord-health.sh" ) | crontab -
  fi
  spin "Sending a test ping" /usr/local/bin/axion-discord-ping.sh "✅ Axion Installer test ping — if you see this, it's wired up correctly."
  hr; ok "Discord status pings configured."; press_enter
}

hx_ddos_basic() {
  need_root; hr; echo -e "  ${C_PURPLE}${C_BOLD}Basic DDoS / abuse mitigation${C_RESET} (iptables rate-limits)"; hr
  warn "This adds conservative rate-limits — not a substitute for a real upstream DDoS filter (Cloudflare/OVH/etc)."
  confirm "Apply basic SYN-flood + per-IP connection-rate limiting now?" || { warn "Cancelled."; press_enter; return; }
  spin "Installing iptables-persistent" bash -c "DEBIAN_FRONTEND=noninteractive apt-get install -y iptables-persistent"
  iptables -N AXION_SYNFLOOD 2>/dev/null || iptables -F AXION_SYNFLOOD
  iptables -C INPUT -p tcp --syn -j AXION_SYNFLOOD 2>/dev/null || iptables -A INPUT -p tcp --syn -j AXION_SYNFLOOD
  iptables -A AXION_SYNFLOOD -m limit --limit 60/s --limit-burst 100 -j RETURN
  iptables -A AXION_SYNFLOOD -j DROP
  iptables -I INPUT -p tcp --syn -m connlimit --connlimit-above 60 --connlimit-mask 32 -j DROP
  spin "Persisting rules" netfilter-persistent save
  hr; ok "Basic SYN-flood + per-IP connection limits applied and persisted."; press_enter
}

hx_librespeed() {
  need_root; hr; echo -e "  ${C_PURPLE}${C_BOLD}LibreSpeed${C_RESET} — your own branded speedtest for customers"; hr
  _ensure_docker
  spin "Running LibreSpeed" docker run -d --restart=always --name librespeed -p 8089:80 adolfintel/speedtest
  local IP; IP=$(hostname -I | awk '{print $1}')
  hr; ok "Speedtest: http://${IP}:8089 — put it behind your own domain/SSL via nginx if you want it customer-facing."
  press_enter
}
